1	// Full-page screenshots for visual QA via the Brave/Chrome CDP session (port 9222).
2	// Usage: node scripts/shot.mjs <url> <out.png> [width] [height] [--full] [--dark|--light] [--scroll N]
3	import { createRequire } from 'node:module';
4	const require = createRequire('C:/Users/Kenneth Rodas/Documents/GitHub/google-flow-mcp/package.json');
5	const { chromium } = require('playwright');
6	
7	const args = process.argv.slice(2);
8	const flags = new Set(args.filter((a) => a.startsWith('--')));
9	const pos = args.filter((a) => !a.startsWith('--'));
10	const [url, out, w = '1440', h = '900'] = pos;
11	const scrollIdx = args.indexOf('--scroll');
12	const scrollTo = scrollIdx >= 0 ? Number(args[scrollIdx + 1]) : 0;
13	
14	const browser = await chromium.connectOverCDP('http://127.0.0.1:9222');
15	const ctx = browser.contexts()[0];
16	const page = await ctx.newPage();
17	await page.setViewportSize({ width: Number(w), height: Number(h) });
18	if (flags.has('--dark') || flags.has('--light')) {
19	  await page.addInitScript((t) => { try { localStorage.setItem('eat.theme', t); } catch (e) { /* ignore */ } }, flags.has('--dark') ? 'dark' : 'light');
20	}
21	const errors = [];
22	page.on('pageerror', (e) => errors.push(`pageerror: ${e.message}`));
23	page.on('console', (m) => { if (m.type() === 'error') errors.push(`console: ${m.text()}`); });
24	page.on('requestfailed', (r) => errors.push(`requestfailed: ${r.url()}`));
25	page.on('response', (r) => { if (r.status() >= 400) errors.push(`${r.status()} ${r.url()}`); });
26	await page.goto(url, { waitUntil: 'networkidle', timeout: 60000 });
27	await page.waitForTimeout(1500);
28	if (scrollTo) { await page.evaluate((y) => window.scrollTo(0, y), scrollTo); await page.waitForTimeout(1200); }
29	if (flags.has('--full')) {
30	  // Trigger all scroll reveals before a full-page capture.
31	  await page.evaluate(async () => {
32	    const total = document.documentElement.scrollHeight;
33	    for (let y = 0; y < total; y += 500) { window.scrollTo(0, y); await new Promise((r) => setTimeout(r, 120)); }
34	    window.scrollTo(0, 0);
35	  });
36	  await page.waitForTimeout(800);
37	}
38	await page.screenshot({ path: out, fullPage: flags.has('--full') });
39	console.log('saved', out, 'errors:', errors.length);
40	for (const e of errors.slice(0, 20)) console.log('  ', e.slice(0, 160));
41	await page.close();
42	await browser.close();
43

