import { createRequire } from 'node:module';
const require = createRequire('C:/Users/Kenneth Rodas/Documents/GitHub/google-flow-mcp/package.json');
const { chromium } = require('playwright');

const BASE = 'http://127.0.0.1:4173';
const OUT = 'C:/Users/Kenneth Rodas/Documents/GitHub/eatdanville/qa/';
const pages = [
  ['home', '/'],
  ['kaias', '/r/kaias/'],
  ['afterdark', '/after-dark/'],
  ['industry', '/industry/'],
  ['partners', '/partners/'],
  ['map', '/map/'],
  ['search', '/search/?q=late%20night'],
];
const sizes = [['d', 1440, 900], ['m', 390, 844]];
const themes = ['light', 'dark'];

const browser = await chromium.connectOverCDP('http://127.0.0.1:9222');
const ctx = browser.contexts()[0];
const allErrors = {};

for (const [name, path] of pages) {
  for (const [sk, w, h] of sizes) {
    for (const th of themes) {
      const page = await ctx.newPage();
      const errs = [];
      page.on('pageerror', (e) => errs.push(`pageerror: ${e.message}`));
      page.on('console', (m) => { if (m.type() === 'error') errs.push(`console: ${m.text()}`); });
      page.on('requestfailed', (r) => errs.push(`requestfailed: ${r.url()}`));
      page.on('response', (r) => { if (r.status() >= 400) errs.push(`${r.status()} ${r.url()}`); });
      await page.addInitScript((t) => { try { localStorage.setItem('eat.theme', t); } catch (e) {} }, th);
      await page.setViewportSize({ width: w, height: h });
      try {
        await page.goto(BASE + path, { waitUntil: 'networkidle', timeout: 60000 });
      } catch (e) { errs.push('goto: ' + e.message); }
      await page.waitForTimeout(1400);
      const tag = `review-design-${name}-${sk}-${th}`;
      await page.screenshot({ path: OUT + tag + '-fold.png' });
      // full page after triggering reveals
      await page.evaluate(async () => {
        const total = document.documentElement.scrollHeight;
        for (let y = 0; y < total; y += 400) { window.scrollTo(0, y); await new Promise((r) => setTimeout(r, 90)); }
        window.scrollTo(0, 0);
      });
      await page.waitForTimeout(700);
      await page.screenshot({ path: OUT + tag + '-full.png', fullPage: true });
      if (errs.length) allErrors[tag] = [...new Set(errs)].slice(0, 12);
      await page.close();
    }
  }
}
console.log(JSON.stringify(allErrors, null, 1));
await browser.close();
EOF
